import re

RULE = re.compile(r"^===-+===$")
TITLE = re.compile(r"^\s{2,}(?P<title>\S.*?)\s*$")
TOTAL = re.compile(r"^\s*Total Execution Time: (?P<seconds>[\d.]+) seconds \((?P<wall>[\d.]+) wall clock\)$")
HEADER = re.compile(r"^\s*(?:-+[^-]+-+\s+)+-+ Name -+\s*$")
CELL = re.compile(r"([\d.]+) \(\s*([\d.]+%)\)")
TIMES = ["User Time", "System Time", "User+System", "Wall Time"]


def parse(lines):
    sections, timers, s_lines, t_lines, skip = [], [], [], [], []
    sec, cols, banner = None, [], None
    for j, ln in enumerate(lines):
        if not ln.strip():
            continue
        if RULE.match(ln):
            skip.append(j)
            banner = None if banner else "open"
            continue
        if banner == "open":
            banner = "titled"
            m = TITLE.match(ln)
            if m:
                sec = {"section": m.group("title"), "Total Execution Time": "", "wall clock": ""}
                sections.append(sec)
                s_lines.append(j)
                continue
        if sec is None:
            continue
        m = TOTAL.match(ln)
        if m:
            sec["Total Execution Time"] = m.group("seconds")
            sec["wall clock"] = m.group("wall")
            s_lines.append(j)
            continue
        if HEADER.match(ln):
            cols = [c.strip("- ") for c in ln.split("  ") if c.strip("- ")][:-1]
            t_lines.append(j)
            continue
        cells = CELL.findall(ln)
        if cols and len(cells) == len(cols):
            name = ln[CELL.search(ln).start():]
            name = CELL.sub("", name).strip()
            rec = {"section": sec["section"], "Name": name}
            for c, (t, p) in zip(cols, cells):
                rec[c], rec[c + " %"] = t, p
            if name == "Total":
                for c in cols:
                    sec["Total " + c] = rec[c]
                s_lines.append(j)
            else:
                timers.append(rec)
                t_lines.append(j)
    cols = [c for c in TIMES if any(c in r for r in timers)]
    keys = ["section", "Name"] + [k for c in cols for k in (c, c + " %")]
    timers = [{k: r.get(k, "") for k in keys} for r in timers]
    skeys = ["section", "Total Execution Time", "wall clock"] + ["Total " + c for c in cols]
    sections = [{k: s.get(k, "") for k in skeys} for s in sections]
    return {"blocks": [{"name": "timers", "kind": "table", "lines": t_lines, "records": timers},
                       {"name": "sections", "kind": "table", "lines": s_lines, "records": sections}],
            "skip": skip}
